def tambah_akun(apps, schema_editor):
    """Idempotent. Dilewati bila COA belum di-setup (klasifikasi Pengeluaran Lain belum ada) --
    seed_coa membuat akun yang sama untuk instalasi baru."""
    Account = apps.get_model("accounting", "Account")
    AccountClassification = apps.get_model("accounting", "AccountClassification")
    FixedAsset = apps.get_model("accounting", "FixedAsset")
    if not AccountClassification.objects.filter(name="Pengeluaran Lain").exists():
        return
    AccountClassification.objects.get_or_create(name=KLASIFIKASI_PAJAK, defaults={
        "account_type": "expense", "order": 4, "code_range_start": 90000, "code_range_end": 99999,
    })
    for kode, nama, klasifikasi, tipe, komponen, ket in AKUN_BARU:
        kls = AccountClassification.objects.filter(name=klasifikasi).first()
        if kls is None or Account.objects.filter(code=kode).exists():
            continue
        Account.objects.create(code=kode, name=nama, account_type=tipe, classification=kls,
                               komponen_ebitda=komponen, description=ket)
    # Akun beban penyusutan yang sudah ada / dipakai register aset ditandai komponen penyusutan.
    Account.objects.filter(code="60400", komponen_ebitda="").update(komponen_ebitda="penyusutan")
    akun_susut = FixedAsset.objects.values_list("depreciation_expense_account_id", flat=True)
    Account.objects.filter(pk__in=akun_susut, komponen_ebitda="").update(komponen_ebitda="penyusutan")


